<script setup lang="ts">
import {ref} from 'vue';import PageShell from '../../components/PageShell.vue';import EmptyState from '../../components/EmptyState.vue';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';import {deviceId} from '../../utils/auth';import {go,money,toast} from '../../utils/format';const rows=ref<any[]>([]),code=ref(''),result=ref<any>(null);const {loading,error,load,busy,action}=usePage(async()=>rows.value=await request('/coupons/center'));async function claim(id?:number){result.value=await request(id?'/coupons/'+id+'/claim':'/coupons/redeem','POST',{deviceId:deviceId(),...(id?{}:{code:code.value})});toast(result.value.success?'优惠券已到账':result.value.reason);await load()}
</script><template><PageShell title="领券中心" back :loading="loading" :error="error" @retry="load"><view class="hero"><view class="hero-title">给毛孩子的<br/>一份暖心礼。</view><text class="subtitle">领取成功后，可在确认订单时使用。</text></view><view class="card"><text class="label">有券码？在这里兑换</text><view class="row"><view class="field" style="flex:1;margin:0"><input v-model="code" placeholder="输入优惠券码"/></view><button class="secondary small" :disabled="busy||!code.trim()" @click="action(()=>claim(),'')">兑换</button></view></view><view class="card" v-for="c in rows" :key="c.id"><view class="row"><text class="amount">{{money(c.amount)}}</text><view><view>{{c.name}}</view><text class="muted">满 {{money(c.threshold)}} 可用 · 每人限 {{c.per_user_limit}} 张</text></view></view><view class="divider"/><view class="row"><text class="muted">剩余 {{c.stock}} 张</text><button class="primary small" :disabled="busy||c.stock<=0" @click="action(()=>claim(c.id),'')">{{c.stock<=0?'已抢光':'立即领取'}}</button></view></view><EmptyState v-if="!rows.length&&!loading" text="暂时没有可领优惠券"/><view v-if="result" class="card"><view style="font-weight:700">{{result.success?'领取成功':'领取未通过'}}</view><view v-for="s in result.chain" :key="s.step" class="menu-item"><text>第 {{s.step}} 步</text><text :class="s.passed?'link':'muted'">{{s.passed?'✓':'×'}} {{s.reason}}</text></view><text class="muted">{{result.nextAction}}</text></view><button class="outline full-width" @click="go('owner/coupon')">查看我的券包</button></PageShell></template>
